CREATE TABLE IF NOT EXISTS fleet_events(id INTEGER PRIMARY KEY,vehicle_id INTEGER NOT NULL REFERENCES erp_objects(id),source_id INTEGER NOT NULL UNIQUE REFERENCES erp_objects(id),entity_id INTEGER NOT NULL REFERENCES erp_entities(id),occurred_at TEXT NOT NULL,event_type TEXT NOT NULL,meter INTEGER NOT NULL DEFAULT 0,quantity INTEGER NOT NULL DEFAULT 0,amount INTEGER NOT NULL DEFAULT 0,driver_id INTEGER REFERENCES erp_objects(id),location TEXT NOT NULL,metadata TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS fleet_events_vehicle_time ON fleet_events(vehicle_id,occurred_at,id);
CREATE INDEX IF NOT EXISTS fleet_events_entity_time ON fleet_events(entity_id,occurred_at,event_type);
CREATE TABLE IF NOT EXISTS fleet_tank_stock(tank_id INTEGER PRIMARY KEY REFERENCES erp_objects(id),quantity INTEGER NOT NULL DEFAULT 0 CHECK(quantity>=0),value INTEGER NOT NULL DEFAULT 0 CHECK(value>=0));
CREATE TABLE IF NOT EXISTS fleet_tank_events(id INTEGER PRIMARY KEY,source_id INTEGER NOT NULL REFERENCES erp_objects(id),tank_id INTEGER NOT NULL REFERENCES erp_objects(id),occurred_at TEXT NOT NULL,kind TEXT NOT NULL,quantity INTEGER NOT NULL,value INTEGER NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS fleet_tank_events_tank_time ON fleet_tank_events(tank_id,occurred_at,id);
CREATE TABLE IF NOT EXISTS fleet_location_permissions(user_id INTEGER NOT NULL REFERENCES users(id),entity_id INTEGER NOT NULL REFERENCES erp_entities(id),location TEXT NOT NULL,allowed INTEGER NOT NULL CHECK(allowed IN(0,1)),PRIMARY KEY(user_id,entity_id,location));
CREATE TABLE IF NOT EXISTS fleet_user_preferences(user_id INTEGER PRIMARY KEY REFERENCES users(id),consumption_alert INTEGER NOT NULL DEFAULT 0,period_days INTEGER NOT NULL DEFAULT 30 CHECK(period_days BETWEEN 1 AND 366),locations TEXT NOT NULL DEFAULT '[]',version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS fleet_import_rows(batch_id INTEGER NOT NULL REFERENCES erp_objects(id),line_number INTEGER NOT NULL,external_key TEXT NOT NULL UNIQUE,raw TEXT NOT NULL,refuel_id INTEGER REFERENCES erp_objects(id),state TEXT NOT NULL,error TEXT,PRIMARY KEY(batch_id,line_number));
CREATE TRIGGER IF NOT EXISTS fleet_events_no_update BEFORE UPDATE ON fleet_events BEGIN SELECT RAISE(ABORT,'Evento de frota preservado'); END;
CREATE TRIGGER IF NOT EXISTS fleet_events_no_delete BEFORE DELETE ON fleet_events BEGIN SELECT RAISE(ABORT,'Evento de frota preservado'); END;
CREATE TRIGGER IF NOT EXISTS fleet_tank_events_no_update BEFORE UPDATE ON fleet_tank_events BEGIN SELECT RAISE(ABORT,'Movimento de tanque preservado'); END;
CREATE TRIGGER IF NOT EXISTS fleet_tank_events_no_delete BEFORE DELETE ON fleet_tank_events BEGIN SELECT RAISE(ABORT,'Movimento de tanque preservado'); END;
